final class Value {
    private final java.util.concurrent.locks.ReentrantReadWriteLock lock =
        new java.util.concurrent.locks.ReentrantReadWriteLock();
    private int value = 10;
    int read() {
        lock.readLock().lock();
        try { return value; } finally { lock.readLock().unlock(); }
    }
    int write(int next) {
        lock.writeLock().lock();
        try { value = next; return value; }
        finally { lock.writeLock().unlock(); }
    }
}

use std::sync::RwLock;
struct Value { value: RwLock<i32> }
impl Value {
    fn new() -> Self { Self { value: RwLock::new(10) } }
    fn read(&self) -> i32 { *self.value.read().unwrap() }
    fn write(&self, next: i32) -> i32 {
        let mut value = self.value.write().unwrap();
        *value = next; *value
    }
}

final class Lazy {
    private volatile Integer value;
    private final java.util.function.IntSupplier build;
    Lazy(java.util.function.IntSupplier build) { this.build = build; }
    int get() {
        Integer result = value;
        if (result == null) {
            synchronized (this) {
                result = value;
                if (result == null) value = result = build.getAsInt();
            }
        }
        return result;
    }
}

use std::sync::OnceLock;
struct Lazy { value: OnceLock<i32> }
impl Lazy {
    fn new() -> Self { Self { value: OnceLock::new() } }
    fn get(&self, build: impl FnOnce() -> i32) -> i32 {
        *self.value.get_or_init(build)
    }
}

final class Ready {
    private boolean ready;
    private int value;
    synchronized int awaitValue() throws InterruptedException {
        while (!ready) wait();
        return value;
    }
    synchronized void publish(int next) {
        value = next; ready = true; notifyAll();
    }
}

use std::sync::{Condvar, Mutex};
struct Ready { value: Mutex<Option<i32>>, changed: Condvar }
impl Ready {
    fn new() -> Self { Self { value: Mutex::new(None), changed: Condvar::new() } }
    fn wait(&self) -> i32 {
        let guard = self.value.lock().unwrap();
        let guard = self.changed.wait_while(guard, |v| v.is_none()).unwrap();
        guard.unwrap()
    }
    fn publish(&self, next: i32) {
        *self.value.lock().unwrap() = Some(next);
        self.changed.notify_all();
    }
}

final class Save {
    private final java.util.concurrent.atomic.AtomicBoolean busy =
        new java.util.concurrent.atomic.AtomicBoolean();
    boolean start() { return busy.compareAndSet(false, true); }
    int finish() { busy.set(false); return 1; }
}

use std::sync::atomic::{AtomicBool, Ordering};
struct Save { busy: AtomicBool }
impl Save {
    fn new() -> Self { Self { busy: AtomicBool::new(false) } }
    fn start(&self) -> bool {
        self.busy.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_ok()
    }
    fn finish(&self) -> i32 { self.busy.store(false, Ordering::Release); 1 }
}

final class LocalCounter {
    private static final ThreadLocal<Integer> count = ThreadLocal.withInitial(() -> 0);
    static int next() {
        int value = count.get() + 1; count.set(value); return value;
    }
    static void clear() { count.remove(); }
}

use std::cell::Cell;
thread_local! { static COUNT: Cell<i32> = const { Cell::new(0) }; }
fn next() -> i32 {
    COUNT.with(|count| { let value = count.get() + 1; count.set(value); value })
}

final class Account {
    private int balance = 10;
    synchronized boolean withdraw(int amount) {
        if (amount < 0 || balance < amount) return false;
        balance -= amount; return true;
    }
    synchronized int read() { return balance; }
}

use std::sync::Mutex;
struct Account { balance: Mutex<i32> }
impl Account {
    fn new() -> Self { Self { balance: Mutex::new(10) } }
    fn withdraw(&self, amount: i32) -> bool {
        let mut balance = self.balance.lock().unwrap();
        if amount < 0 || *balance < amount { return false; }
        *balance -= amount; true
    }
    fn read(&self) -> i32 { *self.balance.lock().unwrap() }
}
